/**
 * @name Regular expression injection
 * @description User input flowing to regex compilation can lead to ReDoS or regex injection
 * @kind path-problem
 * @problem.severity high
 * @id py/regex-injection
 * @tags security
 *        external/cwe/cwe-624
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Regex compilation sinks: re.compile(), regex.compile(), etc.
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("compile").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      call = API::moduleImport("regex").getMember("compile").getACall() and
      sink = call.getArg(0)
    )
    or
    // Regex matching sinks: re.match(), re.search(), re.fullmatch(), re.findall(), re.finditer()
    exists(API::CallNode call |
      (
        call = API::moduleImport("re").getMember(["match", "search", "fullmatch", "findall", "finditer"]).getACall() or
        call = API::moduleImport("regex").getMember(["match", "search", "fullmatch", "findall", "finditer"]).getACall()
      ) and
      sink = call.getArg(0)
    )
    or
    // Pattern object methods: pattern.match(), pattern.search(), etc.
    exists(API::CallNode call, API::Node patternObj |
      patternObj = API::moduleImport("re").getMember("Pattern").getASubclass*() and
      call = patternObj.getMember(["match", "search", "fullmatch", "findall", "finditer"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex injection from $@.", source.getNode(), "user input"

/**
 * @name Command injection
 * @description User input flowing to command execution can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity critical
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // os.system, os.popen, subprocess.call, subprocess.run, etc.
    exists(API::CallNode call |
      (
        call = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall() or
        call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Symlink vulnerability
 * @description User input flowing to symlink-following operations without proper checks
 * @kind path-problem
 * @problem.severity medium
 * @id py/symlink-vulnerability
 * @tags security
 *        external/cwe/cwe-61
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SymlinkConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Functions that follow symlinks by default
    exists(API::CallNode call |
      (
        // os.path functions that follow symlinks
        call = API::moduleImport("os").getMember("path").getMember([
          "exists", "isdir", "isfile", "islink", "getsize", 
          "getmtime", "getatime", "getctime", "samefile"
        ]).getACall() and
        sink = call.getArg(0)
      )
      or
      (
        // os module functions that follow symlinks
        call = API::moduleImport("os").getMember([
          "stat", "lstat", "utime", "chmod", "chown", 
          "access", "listdir", "scandir", "walk"
        ]).getACall() and
        sink = call.getArg(0)
      )
      or
      (
        // pathlib operations that follow symlinks
        call = API::moduleImport("pathlib").getMember("Path").getASubclass*().getMember([
          "exists", "is_dir", "is_file", "is_symlink", "stat", 
          "lstat", "resolve", "absolute"
        ]).getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module SymlinkFlow = TaintTracking::Global<SymlinkConfig>;
import SymlinkFlow::PathGraph

from SymlinkFlow::PathNode source, SymlinkFlow::PathNode sink
where SymlinkFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Symlink vulnerability from $@.", source.getNode(), "user input"
